 P->Id=xrtStrDup(ProviderId);P->Name=xrtStrDup("mdo local");P->Builtin=true;P->Protocols=1;P->TimeoutMilliseconds=600000;P->Endpoints[0]=xrtStrDup("managed:local");P->Proxy=xrtJsonParse(XRT_STR_LITERAL("{\"kind\":\"none\"}"));
